#!/usr/bin/env bash
# seq2cause-bench — the context family's ROOT-CAUSE CASE LEVEL on s and m (seeds 0–4) on one box; generated
# 2026-11-05 from the xs case-level chain of 2026-11-02 (plans/rca-arms.md addendum "2026-10-31, later";
# D-TBR-16 … 19) and the box form of rca-trace-axis-26-10-31.sh. Per corpus: pull rca → export (asserted equal
# to the landed export-trace record) → per probe layout (core overwrite = the IG and CMI cells of one forward;
# core keep; atomic CMI) and phase (post = the fault window, pre = the pre-fault stretch): one probe of the
# first 500 window traces per case by start time, the readings hop1 / hop0 / source re-ranking the shared
# --work-dir (`runner_reused`); the post − pre rows (`--subtract pre`) per arm and reading; the landed arms
# rca/trace and rca/trace-core at hop0 and source from a re-probe of the landed selection at the cap of 500
# (the 2026-10-30 work files are gone; the addendum's fallback, as at xs); control/trace-earliest; rm raw.
# Staging: every s row names the xs row of the same seed, arm and series through the ledger (the entries of
# 2026-11-02); every m row names the s row of this chain (form record). Probes on the A10G (--device cuda;
# the xs rows ran on the CPU; the landed per-trace axis of s and m ran on cuda). The frozen cells are read
# from the committed context freezes (2026-11-01, s and m) and, for the landed arms, the landed model
# freezes; every run hash-checks the backbone at input/<rung>-s<k>/model against the freeze. Scoring
# (tracebenchrca.score, B = 2000) runs locally on landing. Last line: the sibling's artifacts manifest.
# One command per line; the runner's cwd is benchmarks/trace-bench-rca; set -e stops at the first failure.
set -euo pipefail
TP=$HOME/miniforge3/envs/seq2cause-trace-bench/bin/python
HR=../..
L=../trace-bench/plans/staging-ledger.json

python -m tracebenchrca.pull --repo chadyuk/trace-bench --revision v0.3.0 --rung s --variant latent --seed 0 --tier rca --dest corpora --output-folder out/rca-ctx/s-s0/pull-rca-ctx
python -m tracebenchrca.export --corpus-dir corpora/instances/s/latent/seed=0 --rung s --out exports/s-s0 --workers 4 --extras --expect-cases results/s/latent/seed=0/export-trace/run/results.json --output-folder out/rca-ctx/s-s0/export-ctx
python -m tracebenchrca.ranktrace --arm rca/trace-ig-overwrite --probe-arms rca/trace-ig-overwrite rca/trace-cmi-overwrite --reading hop1 --phase post --subtract none --pre-record none --export-record out/rca-ctx/s-s0/export-ctx --corpus-dir corpora/instances/s/latent/seed=0 --model-dir input/s-s0/model --rung s --seed 0 --trace-python $TP --harness-root $HR --device cuda --staging-ledger $L --axis ranking --select window --cap 500 --prior-rung-record 3a20c6a8f5ebb1f74064384fbd79796182269dfc7943a60344c8c0ba65bcfeb3 --freeze ../trace-bench/freezes/2026-11-01-s-latent-s0-context.json --work-dir out/rca-ctx/work/s-s0-core-ow-post --output-folder out/rca-ctx/s-s0/rca-trace-ig-overwrite/hop1/rank
python -m tracebenchrca.ranktrace --arm rca/trace-ig-overwrite --probe-arms rca/trace-ig-overwrite rca/trace-cmi-overwrite --reading hop0 --phase post --subtract none --pre-record none --export-record out/rca-ctx/s-s0/export-ctx --corpus-dir corpora/instances/s/latent/seed=0 --model-dir input/s-s0/model --rung s --seed 0 --trace-python $TP --harness-root $HR --device cuda --staging-ledger $L --axis ranking --select window --cap 500 --prior-rung-record 95744ace20fd2b8456d2b9f0d86a7b83378958d170e425dc7127c4a9481c1ed9 --freeze ../trace-bench/freezes/2026-11-01-s-latent-s0-context.json --work-dir out/rca-ctx/work/s-s0-core-ow-post --output-folder out/rca-ctx/s-s0/rca-trace-ig-overwrite/hop0/rank
